const params=new URLSearchParams(location.search),variant=['a','b','c'].includes(params.get('v'))?params.get('v'):'a';
let view=params.get('view')||'library',filter='全部',query='',chatOpen=true,sourceExpanded=false,sourceAttached=true,messages=[],saved=false,selectedFolder='全部书籍',activeBook=0,replyTimer;
const books=[
  {title:'慢读的方法',author:'陈见',format:'EPUB',progress:38,chapter:'第二章 · 把阅读变成理解',notes:8,time:'刚刚',tone:'sage',folder:'阅读与思考',subtitle:'让文字成为自己的经验'},
  {title:'山河小记',author:'林溪',format:'EPUB',progress:64,chapter:'第三章 · 山间来信',notes:12,time:'昨天',tone:'sand',folder:'文学与故事',subtitle:'在行走中重新认识日常'},
  {title:'日常设计札记',author:'余白',format:'PDF',progress:21,chapter:'第 28 页',notes:3,time:'昨天',tone:'blue',folder:'设计与技术',subtitle:'关于事物与人的观察'},
  {title:'长夜里的灯塔',author:'周遥',format:'在线',progress:12,chapter:'第十二章 · 远方的回声',notes:2,time:'周三',tone:'ink',folder:'文学与故事',subtitle:'夜色深处，仍有微光'},
  {title:'时间的形状',author:'许原',format:'TXT',progress:0,chapter:'尚未开始',notes:0,time:'周二',tone:'rust',folder:'阅读与思考',subtitle:'把目光放回此刻'},
  {title:'缓慢的观察',author:'苏禾',format:'EPUB',progress:100,chapter:'已读完',notes:16,time:'上周',tone:'plum',folder:'设计与技术',subtitle:'记录那些细小而具体的事'}
];
const icons={book:'<path d="M3 4.5c3-1 6-.5 9 1.5 3-2 6-2.5 9-1.5v15c-3-1-6-.5-9 1.5-3-2-6-2.5-9-1.5z"/><path d="M12 6v15"/>',note:'<path d="M14 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-9"/><path d="m16 3 5 5-9 9-5 1 1-5zM7 6h3"/>',search:'<circle cx="10.8" cy="10.8" r="7.3"/><path d="m16.2 16.2 4.7 4.7"/>',plus:'<path d="M12 5v14M5 12h14"/>',folder:'<path d="M3 7V5a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/>',chevron:'<path d="m8 10 4 4 4-4"/>',right:'<path d="m9 5 7 7-7 7"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>',up:'<path d="M12 20V4m-6 6 6-6 6 6"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 14v6h16v-6"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',list:'<path d="M8 5h13M8 12h13M8 19h13M3 5h.1M3 12h.1M3 19h.1"/>',sort:'<path d="M8 4v16m-4-4 4 4 4-4M16 4h5M16 10h4M16 16h2"/>',sliders:'<path d="M5 3v6m0 4v8M12 3v10m0 4v4M19 3v2m0 4v12M2 9h6M9 17h6M16 5h6"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/>',chat:'<path d="M21 16a2 2 0 0 1-2 2H8l-5 3V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2zM7 8h10M7 12h6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',minus:'<path d="M5 12h14"/>',external:'<path d="M14 3h7v7M21 3l-11 11M10 3H4v17h17v-6"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',check:'<path d="m5 12 4 4 10-10"/>',history:'<path d="M3 3v6h6M3.5 9a9 9 0 1 1-.2 6M12 7v5l4 2"/>',bookmark:'<path d="M6 3h12v18l-6-4-6 4z"/>',panel:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M15 4v16"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',link:'<path d="m10 13 4-4m-6 7-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m2-1 2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z"/>'};
const icon=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.55" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.book}</svg>`;
const ib=(name,label,action='notice')=>`<button class="icon-btn" aria-label="${label}" title="${label}" data-action="${action}">${icon(name)}</button>`;
const esc=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function cover(b,extra=''){return `<div class="cover ${b.tone} ${extra}"><span class="cover-edition">READER EDITIONS</span><strong>${b.title}</strong><span class="cover-subtitle">${b.subtitle}</span><i class="cover-art"></i><small>${b.author} <span>著</span></small></div>`;}
function sidebar(){return `<aside class="sidebar"><div class="side-brand"><span class="brand-mark">r.</span><b>Reader</b>${ib('panel','收起导航','collapse-nav')}</div><nav class="main-nav"><button class="nav-item active" data-action="library">${icon('book')}<span>书库</span><small>6</small></button><button class="nav-item" data-action="notes">${icon('note')}<span>笔记</span><small>41</small></button><button class="nav-item" data-action="search">${icon('search')}<span>搜索</span><kbd>Ctrl K</kbd></button></nav><div class="folder-label"><span>文件夹</span>${ib('plus','新建文件夹','notice')}</div><nav class="folder-nav">${['全部书籍','文学与故事','阅读与思考','设计与技术'].map((f,i)=>`<button class="folder-item ${selectedFolder===f?'selected':''}" data-folder="${f}">${i?icon('folder',15):icon('book',15)}<span>${f}</span><small>${i?2:6}</small></button>`).join('')}</nav><div class="sidebar-bottom"><button class="nav-item" data-action="notice">${icon('trash')}<span>回收站</span></button><button class="nav-item" data-action="appearance">${icon('sliders')}<span>外观</span></button><div class="local-status"><i></i><span>本地书库</span></div></div></aside>`;}
function topnav(){return `<header class="topnav"><div class="top-brand"><span class="brand-mark">r.</span><strong>Reader</strong></div><nav><button class="active" data-action="library">书库</button><button data-action="notes">笔记</button><button data-action="search">搜索</button></nav><div>${ib('sliders','外观','appearance')}<button class="plain-btn" data-action="import">${icon('plus',16)}导入书籍</button></div></header>`;}
function rail(){return `<aside class="rail"><span class="brand-mark">r.</span>${ib('book','书库','library')}${ib('note','笔记','notes')}${ib('search','搜索','search')}<span class="rail-divider"></span>${ib('folder','文件夹','folders')}<div class="rail-bottom">${ib('trash','回收站')}${ib('sliders','外观','appearance')}</div></aside>`;}
function heading(){return `<div class="page-heading"><div><h1>书库<span>6 本</span></h1>${variant==='b'?'<p>读过的，正在读的，还有想读的。</p>':''}</div><div class="heading-actions">${variant==='b'?ib('more','更多书库操作'):`<button class="primary-btn" data-action="import">${icon('plus',16)}导入书籍</button>`}</div></div>`;}
function resumeCard(b,index=0){return `<article class="resume-card"><button class="resume-cover" data-book="${index}" aria-label="继续阅读 ${b.title}">${cover(b)}</button><div class="resume-info"><span class="eyebrow">${variant==='b'?'继续上次的阅读':'继续阅读'}</span><h2>${b.title}</h2><p>${b.chapter}</p><div class="resume-progress"><span class="progress-line"><i style="width:${b.progress}%"></i></span><small>${b.progress}%</small></div></div><button class="continue-btn ${variant==='a'?'primary-btn':'soft-btn'}" data-book="${index}">接着读 ${icon('arrow',17)}</button></article>`;}
function controls(){return `<div class="library-controls"><label class="searchbox">${icon('search',17)}<input id="search" placeholder="搜索书名或作者" aria-label="搜索书名或作者" value="${esc(query)}"><kbd>Ctrl K</kbd></label><div class="filters" aria-label="书籍格式">${['全部','EPUB','TXT','PDF','在线'].map(x=>`<button data-filter="${x}" class="${filter===x?'active':''}">${x}</button>`).join('')}</div><div class="view-controls">${ib('sort','按最近阅读排序','sort')}${ib(variant==='b'?'grid':'list','切换书库视图','toggle-layout')}</div></div>`;}
function bookRows(items){return `<div class="book-table"><div class="table-head"><span>书名</span><span>阅读进度</span><span>最近打开</span><span></span></div>${items.map(b=>`<div class="book-row" data-title="${b.title}"><button class="book-cell" data-book="${books.indexOf(b)}">${cover(b,'tiny')}<span><strong>${b.title}</strong><small>${b.author}<i>·</i>${b.format}<i>·</i>${b.notes} 篇笔记</small></span></button><button class="progress-cell" data-book="${books.indexOf(b)}"><span>${b.progress===100?'已读完':b.progress===0?'未开始':`已读 ${b.progress}%`}</span><span class="progress-line"><i style="width:${b.progress}%"></i></span></button><span class="time-cell">${b.time}</span>${ib('more',`管理 ${b.title}`)}</div>`).join('')}</div>`;}
function bookGrid(items){return `<div class="book-grid">${items.map(b=>`<article class="grid-book"><button data-book="${books.indexOf(b)}" class="cover-button" aria-label="阅读 ${b.title}">${cover(b)}<span class="format-tag">${b.format}</span></button><div class="grid-book-info"><button data-book="${books.indexOf(b)}">${b.title}</button>${ib('more',`管理 ${b.title}`)}</div><p>${b.author}<span>${b.progress===100?'已读完':b.progress===0?'未开始':`${b.progress}%`}</span></p><div class="progress-line"><i style="width:${b.progress}%"></i></div></article>`).join('')}</div>`;}
function noteItems(){return `<button class="note-row" data-action="note-open">${icon('note',18)}<span><strong>把阅读变成自己的经验</strong><small>慢读的方法 · 3 条引用</small></span><time>今天</time>${icon('right',15)}</button><button class="note-row" data-action="note-open">${icon('note',18)}<span><strong>关于观察与记录</strong><small>山河小记 · 2 条引用</small></span><time>昨天</time>${icon('right',15)}</button>`;}
function notes(){return `<section class="recent-notes"><div class="section-heading"><h2>最近的笔记</h2><button class="text-btn" data-action="notes">全部笔记 ${icon('arrow',14)}</button></div>${noteItems()}</section>`;}
function notesRail(){return `<aside class="notes-rail"><div class="section-heading"><h2>阅读笔记</h2>${ib('plus','新建笔记')}</div><p class="muted note-date">今天</p><button class="pinned-note" data-action="note-open"><span class="note-label">${icon('note',14)}慢读的方法</span><h3>把阅读变成<br>自己的经验</h3><p>理解不只是记住原句，而是能够用自己的话解释，再放进新的情境。</p><span class="note-foot">3 条引用${icon('arrow',15)}</span></button><p class="muted note-date">昨天</p><button class="pinned-note compact" data-action="note-open"><span class="note-label">${icon('note',14)}山河小记</span><h3>关于观察与记录</h3><p>把注意力留给具体的事物。</p><span class="note-foot">2 条引用${icon('arrow',15)}</span></button><button class="text-btn" data-action="notes">查看全部笔记 ${icon('arrow',15)}</button></aside>`;}
function library(){let items=books.filter(b=>(filter==='全部'||b.format===filter)&&(!query||`${b.title}${b.author}`.includes(query))&&(selectedFolder==='全部书籍'||selectedFolder===b.folder));let content;if(variant==='c'&&filter==='全部'&&!query&&selectedFolder==='全部书籍'){content=`<div class="group-label">${icon('chevron',14)} 正在阅读 <span>4</span></div>${bookRows(items.filter(b=>b.progress>0&&b.progress<100))}<div class="group-label">${icon('chevron',14)} 稍后阅读 <span>1</span></div>${bookRows(items.filter(b=>!b.progress))}<div class="group-label">${icon('chevron',14)} 已读完 <span>1</span></div>${bookRows(items.filter(b=>b.progress===100))}`;}else content=variant==='b'?bookGrid(items):bookRows(items);if(!items.length)content='<div class="empty-results">没有找到这本书<button class="text-btn" data-action="reset-search">清除筛选</button></div>';
return `<div class="workspace library-workspace ${variant==='b'?'with-topnav':''}">${variant==='b'?topnav():variant==='c'?rail():sidebar()}<main class="library-main">${variant==='c'?'<div class="breadcrumb">我的空间 <span>/</span> 书库</div>':''}${heading()}${variant==='b'?`<div class="recent-reading">${resumeCard(books[0])}${resumeCard(books[1],1)}</div>`:resumeCard(books[0])}${variant==='b'?'<div class="section-heading shelf-section-title"><h2>全部书籍</h2><button class="text-btn" data-action="folders">按文件夹浏览 '+icon('chevron',14)+'</button></div>':''}${controls()}<div id="book-results">${content}</div>${variant==='c'?'':notes()}</main>${variant==='c'?notesRail():''}</div>`;}
const passage='<p>读完一页之后，我们常常觉得自己已经理解了。熟悉的词语和轻轻点头的时刻，会让阅读显得毫不费力。</p><p>但当我们合上书，试着向另一个人解释刚才读到的内容，那些清晰的句子，有时就变得模糊。我们记住了作者的声音，却还没有形成自己的说法。</p><p><mark>当我们能用自己的话解释一个观点，并把它放进新的情境里，阅读才开始成为自己的经验。</mark></p><p>所以，慢读并不是每个字都读得更慢。它更像是在重要的地方停一下，问问自己：这句话在回答什么问题？我是否同意它？它和我已经知道的事情有什么关系？</p><h2>给问题留一个位置</h2><p>一个暂时没有答案的问题，也是一种有价值的阅读记录。我们不必立刻整理出漂亮的结论，可以先保留疑问，等下一次阅读时把它连接起来。</p><p>在纸页空白的地方，写下一个小小的例子。它未必完整，却能让一句抽象的话与真实生活发生联系。</p>';
function reader(){return `<div class="workspace reader-workspace"><header class="reader-header"><button class="back-btn" data-action="library">${icon('back',17)}<span>书库</span></button><span class="reader-separator"></span><span class="reader-book-title">${books[activeBook].title}</span><span class="reader-author">${books[activeBook].author}</span><div class="reader-tools">${ib('list','目录','contents')}${ib('search','书内搜索')}${ib('sliders','阅读外观','appearance')}<i></i>${ib('bookmark','书签','bookmark')}${ib('chat','阅读对话','open-chat')}${ib('note','笔记','notes')}</div></header><div class="reader-canvas"><article class="reading-text"><div class="chapter-eyebrow">第二章</div><h1>把阅读变成理解</h1><p class="chapter-intro">读过的文字，如何成为自己的经验？</p>${passage}</article><div class="selection-toolbar"><button data-action="highlight">${icon('bookmark',16)}</button><button data-action="note-open">${icon('note',16)}</button><button data-action="open-chat">${icon('chat',16)}问 Codex</button></div>${chatOpen?chat():`<button class="chat-bubble" data-action="open-chat" aria-label="继续阅读对话">${icon('chat',20)}</button>`}</div><footer class="reader-footer"><span>第二章 · 把阅读变成理解</span><div><span>${icon('check',13)}位置已保存</span><span class="footer-progress">38%</span></div></footer></div>`;}
function chat(){return `<section class="chat-window" role="dialog" aria-label="阅读对话"><header class="chat-header"><button class="topic-button" data-action="topics">${icon('chat',17)}<span>阅读对话</span>${icon('chevron',13)}</button><div class="chat-tools">${ib('plus','新话题','new-topic')}${ib('more','更多对话操作','chat-menu')}${ib('minus','收起对话','minimize')}${ib('close','关闭对话','close-chat')}</div></header><div class="chat-topic-line"><span>从读懂，到真正理解</span><small>演示</small></div><div class="chat-log" role="log" aria-label="对话消息"><div class="user-message">这段话里的“自己的经验”，<br>应该怎么理解？</div><div class="assistant-message"><p>关键是从<strong>“记住作者说了什么”</strong>，走到<strong>“我能用它解释什么”</strong>。</p><p>可以试着做两件小事：</p><ol><li><strong>换一种说法。</strong>合上书，用自己的话向朋友解释这个观点。</li><li><strong>放进一个新例子。</strong>找一件生活中的事，看看这个观点是否适用。</li></ol><p>能够解释，也能够迁移到新的情境，理解才慢慢变成自己的经验。</p><button class="citation" data-action="source-jump">${icon('book',13)}慢读的方法 · 第 2 章 ${icon('right',12)}</button><div class="message-actions">${ib('copy','复制回答','copy')}${ib('note',saved?'已保存为笔记':'保存为笔记','save-note')}${saved?'<small>已保存到示例笔记</small>':''}</div></div>${messages.map(m=>`<div class="${m.role==='user'?'user-message':'assistant-message'}"><p>${esc(m.text)}</p></div>`).join('')}</div><div class="chat-bottom">${sourceAttached?`<button class="context-chip" data-action="source-toggle" aria-expanded="${sourceExpanded}">${icon('link',14)}<span>选中段落</span><small>· 第 2 章</small>${icon(sourceExpanded?'minus':'chevron',13)}</button>`:''}${sourceExpanded&&sourceAttached?`<div class="source-preview"><p>当我们能用自己的话解释一个观点，并把它放进新的情境里，阅读才开始成为自己的经验。</p><button class="text-btn" data-action="source-remove">移除此引用</button></div>`:''}<form class="composer"><textarea aria-label="继续追问" placeholder="继续追问，或聊聊你的理解…" rows="2"></textarea><div class="composer-tools">${ib('plus','添加引用','attach')}<button type="button" class="scope-button" data-action="scope">仅所选内容 ${icon('chevron',12)}</button><button type="submit" class="send-btn" aria-label="发送问题">${icon('up',18)}</button></div></form><div class="chat-bottom-line"><span><i class="status-dot"></i>阅读助手</span><button data-action="handoff">在 Codex 中继续 ${icon('external',11)}</button></div></div></section>`;}
function render(){document.body.className=`prototype variant-${variant} view-${view} ${params.has('detail')?'detail':''}`;document.getElementById('app').innerHTML=view==='library'?library():reader();bind();}
function showToast(text){document.querySelector('.toast')?.remove();let el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=text;document.body.append(el);setTimeout(()=>el.remove(),3200);}
function showDialog(title,body){document.querySelector('.modal-backdrop')?.remove();const el=document.createElement('div');el.className='modal-backdrop';el.innerHTML=`<section class="preview-dialog" role="dialog" aria-label="${esc(title)}"><header><h2>${esc(title)}</h2>${ib('close','关闭弹层','dismiss')}</header>${body}</section>`;document.body.append(el);el.querySelector('[data-action="dismiss"]').onclick=()=>el.remove();el.onclick=e=>{if(e.target===el)el.remove();};el.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{showToast(b.textContent+' · 演示');el.remove();});el.querySelector('button')?.focus();}
function action(name){switch(name){case 'library':view='library';render();break;case 'open-chat':chatOpen=true;view='reader';render();break;case 'minimize':case 'close-chat':chatOpen=false;render();break;case 'source-toggle':sourceExpanded=!sourceExpanded;render();break;case 'source-remove':sourceAttached=false;render();break;case 'attach':sourceAttached=true;render();break;case 'source-jump':document.querySelector('mark')?.scrollIntoView({behavior:'smooth',block:'center'});showToast('已定位到示例原文');break;case 'search':if(view!=='library'){view='library';render();}document.getElementById('search')?.focus();break;case 'reset-search':query='';filter='全部';render();break;case 'save-note':saved=true;render();showToast('回答已加入示例笔记');break;case 'copy':showToast('设计演示：复制此条回答');break;case 'notes':case 'note-open':showDialog('把阅读变成自己的经验','<p class="dialog-source">慢读的方法 · 第 2 章</p><blockquote>理解不只是记住原句，而是能够用自己的话解释，再放进新的情境。</blockquote><textarea aria-label="示例笔记">先用一句话解释，再举一个新例子。下次阅读时，试着把这两个步骤写下来。</textarea><p class="dialog-hint">示例笔记 · 仅供预览</p>');break;case 'import':showDialog('导入书籍',`<div class="import-demo">${icon('upload',28)}<h3>把想读的书放进来</h3><p>EPUB、PDF、TXT</p><button class="primary-btn" data-choice>选择文件（演示）</button></div>`);break;case 'topics':showDialog('阅读对话','<button class="dialog-choice" data-choice>从读懂，到真正理解 <small>今天</small></button><button class="dialog-choice" data-choice>如何给问题留一个位置 <small>昨天</small></button>');break;case 'new-topic':messages=[];showToast('新话题入口 · 设计演示');break;case 'chat-menu':showDialog('对话操作','<button class="dialog-choice" data-choice>对话历史</button><button class="dialog-choice" data-choice>展开对话</button><button class="dialog-choice" data-choice>在 Codex 中继续</button>');break;case 'scope':showDialog('本次提问的内容范围','<button class="dialog-choice" data-choice>✓ 仅所选内容</button><button class="dialog-choice" data-choice>允许读取本书</button><p class="dialog-hint">这份设计预览不会读取或发送书籍内容。</p>');break;case 'handoff':showDialog('在 Codex 中继续','<p>将选择的引用与当前问题带入 Codex 原生对话。</p><blockquote>慢读的方法 · 第 2 章<br>这段话里的“自己的经验”，应该怎么理解？</blockquote><button class="primary-btn" data-choice>预览交接内容</button>');break;case 'toggle-layout':document.querySelector('#book-results').classList.toggle('alternate-layout');showToast('已切换列表密度');break;case 'sort':document.querySelectorAll('.book-table').forEach(table=>{[...table.querySelectorAll('.book-row')].reverse().forEach(row=>table.append(row));});showToast('已反转示例排序');break;case 'collapse-nav':document.querySelector('.sidebar')?.classList.toggle('collapsed');break;case 'folders':showDialog('文件夹',books.slice(0,3).map(b=>`<button class="dialog-choice" data-choice>${b.folder}<small>2 本</small></button>`).join(''));break;case 'appearance':showDialog('外观','<p>本提案使用 '+({a:'中性浅色',b:'暖白纸色',c:'中性深色'}[variant])+'。可在预览顶部切换三套设计。</p><p class="dialog-hint">正式实现建议跟随宿主明暗，阅读纸色单独配置。</p>');break;case 'contents':showDialog('目录','<button class="dialog-choice" data-choice>01 给阅读留一点空白</button><button class="dialog-choice" data-choice>02 把阅读变成理解</button><button class="dialog-choice" data-choice>03 让问题继续生长</button>');break;default:showToast('此入口为视觉设计示意');}}
function bind(){document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();action(b.dataset.action);}));document.querySelectorAll('[data-book]').forEach(b=>b.onclick=()=>{activeBook=Number(b.dataset.book);view='reader';chatOpen=true;render();});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render();});document.querySelectorAll('[data-folder]').forEach(b=>b.onclick=()=>{selectedFolder=b.dataset.folder;render();});const search=document.getElementById('search');if(search)search.oninput=()=>{query=search.value;const caret=search.selectionStart;render();const next=document.getElementById('search');next.focus();next.setSelectionRange(caret,caret);};const form=document.querySelector('.composer');if(form){const send=()=>{const input=form.querySelector('textarea'),text=input.value.trim();if(!text)return;messages.push({role:'user',text},{role:'assistant',text:'示例回答：可以先用一句话解释这个观点，再写一个与自己有关的新例子，最后回到原文核对。'});render();document.querySelector('.chat-log').scrollTop=10000;};form.onsubmit=e=>{e.preventDefault();send();};form.querySelector('textarea').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();send();}};}}
document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelector('.modal-backdrop')?.remove();}if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();action('search');}});render();
